package hkmc2.ctml

import org.scalatest.BeforeAndAfterEach
import org.scalatest.funsuite.AnyFunSuite

import hkmc2.ctml.config.*
import hkmc2.ctml.core.clauses.*
import hkmc2.ctml.core.context.*
import hkmc2.ctml.core.subtyping.*
import hkmc2.ctml.core.var_.*
import hkmc2.ctml.types.*

/** Effective bounds retain obligations generated by opposite-bound propagation. */
class EffectivePropagationTest extends AnyFunSuite with BeforeAndAfterEach:
  /** Keep all controls bounded and isolate checker configuration and fresh identities. */
  override def beforeEach(): Unit =
    super.beforeEach()
    resetConfig()
    resetFreshVarCounter()
    config.searchSteps = Some(5000)

  /** Restore the ordinary checker policy for later suites. */
  override def afterEach(): Unit =
    try resetConfig()
    finally super.afterEach()

  /** Shared ordinary flexible context with disjoint inhabited primitive classes. */
  private def context(x: TypeVar): SubContext = SubContext.empty
    .declClass("Int", None).declClass("Str", None).declTypeVar(x, TypeVarKind.Flex)

  /** Exercise either polarity of feedback and compare cached lookup to asserted obligations. */
  private def checkFeedback(codomain: Type, complemented: Boolean): Unit =
    val x = TypeVar("X")
    val int = TClass(ClassVar("Int"))
    val active = if complemented then TNeg(TVar(x)) else TVar(x)
    val anyFunction = TLam(TTop, codomain)
    val upper = TLam(anyFunction, codomain)
    val lower = TLam(active, int)
    val smaller = TLam(TLam(TTop, int), int)
    given SubContext = context(x)
    val setup = subtype(active, upper)
    val result = subtypeSeq(lower, active, setup)
    intercept[TypeError](subtype(anyFunction, smaller))
    intercept[TypeError](subtypeSeq(active, smaller, result.removeEffectiveBounds()))
    intercept[TypeError](subtypeSeq(active, smaller, result))
    subtypeSeq(active, upper, result)
    subtypeSeq(anyFunction, active, result)

  test("propagated lower obligations remain visible behind the effective bound"):
    checkFeedback(TTop, false)

  test("propagated upper obligations remain visible behind the effective bound"):
    checkFeedback(TTop, true)

  test("proper-codomain feedback preserves its necessary lower obligation"):
    checkFeedback(TJointType(JointMode.Union,
      TClass(ClassVar("Int")), TClass(ClassVar("Str"))), false)

  test("proper-codomain feedback preserves its necessary upper obligation"):
    checkFeedback(TJointType(JointMode.Union,
      TClass(ClassVar("Int")), TClass(ClassVar("Str"))), true)

  test("variable relations retain lower obligations discovered during contravariant propagation"):
    val x = TypeVar("X")
    val y = TypeVar("Y")
    val int = TClass(ClassVar("Int"))
    val wide = TJointType(JointMode.Union, int, TClass(ClassVar("Str")))
    val anyFunction = TLam(TTop, wide)
    val upper = TLam(anyFunction, wide)
    val smaller = TLam(TLam(TTop, int), int)
    given SubContext = context(x).declTypeVar(y, TypeVarKind.Flex)
    val setup = subtype(TVar(y), upper)
    val lower = subtypeSeq(TLam(TVar(y), int), TVar(x), setup)
    val result = subtypeSeq(TVar(x), TVar(y), lower)
    assert(summon[SubContext].extend(result).findEscapedVars().isEmpty)
    intercept[TypeError](subtypeSeq(TVar(y), smaller, result.removeEffectiveBounds()))
    intercept[TypeError](subtypeSeq(TVar(y), smaller, result))

  test("variable relations retain upper obligations discovered at a higher inference level"):
    val p = TypeVar("P")
    val q = TypeVar("Q")
    val int = TClass(ClassVar("Int"))
    val wide = TJointType(JointMode.Union, int, TClass(ClassVar("Str")))
    val anyFunction = TLam(TTop, wide)
    val upper = TLam(anyFunction, wide)
    val smaller = TLam(TLam(TTop, int), int)
    given SubContext = context(q).mapLevel(_ + 1).declTypeVar(p, TypeVarKind.Flex)
    val setup = subtype(TNeg(upper), TVar(p))
    val lower = subtypeSeq(TVar(q), TNeg(TLam(TNeg(TVar(p)), int)), setup)
    val result = subtypeSeq(TVar(p), TVar(q), lower)
    assert(summon[SubContext].extend(result).findEscapedVars().isEmpty)
    intercept[TypeError](subtypeSeq(TNeg(smaller), TVar(p), result.removeEffectiveBounds()))
    intercept[TypeError](subtypeSeq(TNeg(smaller), TVar(p), result))
